'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
function setup(){const c={window:{}};vm.createContext(c);for(const f of ['white-orchard.js','map-data.js','diagrams-data.js','exploration-data.js','exploration-art.js'])vm.runInContext(fs.readFileSync(f,'utf8'),c);return c.window;}
test('every task and category has a distinct, locally available credited image',()=>{const w=setup(),a=w.PHOENIX_EXPLORATION_ART,ids=[...Object.keys(w.PHOENIX_EXPLORATION.details),...w.PHOENIX_EXPLORATION.categories.map(c=>'category-'+c.id),'category-diagrams'];assert.equal(ids.length,55);assert.equal(new Set(ids.map(id=>a[id]?.src)).size,55);assert.equal(new Set(ids.map(id=>a[id]?.sha256)).size,55);for(const id of ids){assert.ok(a[id],id);assert.ok(fs.statSync(a[id].src).size>10000,id+' missing/empty image');assert.ok(a[id].sourcePage);assert.ok(a[id].sourceImage);assert.ok(a[id].credit);assert.ok(['map','landmark','scene','illustration'].includes(a[id].kind));}});
test('illustrated scenes retain location provenance and sharp source dimensions',()=>{const w=setup();for(const [id,a] of Object.entries(w.PHOENIX_EXPLORATION_ART)){assert.equal(a.kind,'illustration',id);assert.ok(a.referenceImage,id);assert.ok(['map','landmark','scene'].includes(a.referenceKind),id);assert.ok(a.originalSize[0]>=1024&&a.originalSize[1]>=1024,id);assert.match(a.credit,/reconstruction/i);}});
